Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"
$env:GIT_PAGER = "cat"
$env:NPM_CONFIG_LOGLEVEL = "error"

$Root = (Get-Location).Path
$ManagerRelative = "components/food/DeliveriesManager.tsx"
$ManagerPath = Join-Path $Root "components\food\DeliveriesManager.tsx"
$OperationsRelative = "components/food/DeliveryDriverOperations.tsx"
$OperationsPath = Join-Path $Root "components\food\DeliveryDriverOperations.tsx"
$MigrationDirectory = Join-Path $Root "supabase\migrations"
$BackupDirectory = Join-Path $Root ".orcaly-backups"
$Timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$BackupRoot = Join-Path $BackupDirectory "delivery-drivers-$Timestamp"
$ManagerBackup = Join-Path $BackupRoot "DeliveriesManager.tsx"
$OperationsBackup = Join-Path $BackupRoot "DeliveryDriverOperations.tsx"
$HadOperations = Test-Path -LiteralPath $OperationsPath
$MigrationCreated = $false
$MigrationPath = ""

$ComponentBase64 = @'

'@

$MigrationBase64 = @'

'@

$PatcherBase64 = @'

'@

function Write-Section([string]$Text) {
    Write-Host ""
    Write-Host ("=" * 72) -ForegroundColor DarkCyan
    Write-Host $Text -ForegroundColor Cyan
    Write-Host ("=" * 72) -ForegroundColor DarkCyan
}

function Write-Utf8File(
    [string]$Path,
    [string]$Base64
) {
    $Parent = Split-Path -Parent $Path

    if ($Parent) {
        New-Item `
            -ItemType Directory `
            -Path $Parent `
            -Force | Out-Null
    }

    $Clean = $Base64 -replace "\s", ""
    $Bytes = [Convert]::FromBase64String($Clean)
    [System.IO.File]::WriteAllBytes($Path, $Bytes)
}

function Restore-Files {
    Write-Host "[AVISO] Restaurando arquivos anteriores..." -ForegroundColor Yellow

    if (Test-Path -LiteralPath $ManagerBackup) {
        Copy-Item `
            -LiteralPath $ManagerBackup `
            -Destination $ManagerPath `
            -Force
    }

    if (Test-Path -LiteralPath $OperationsBackup) {
        Copy-Item `
            -LiteralPath $OperationsBackup `
            -Destination $OperationsPath `
            -Force
    }
    elseif (
        -not $HadOperations -and
        (Test-Path -LiteralPath $OperationsPath)
    ) {
        Remove-Item `
            -LiteralPath $OperationsPath `
            -Force
    }

    if (
        $MigrationCreated -and
        $MigrationPath -and
        (Test-Path -LiteralPath $MigrationPath)
    ) {
        Remove-Item `
            -LiteralPath $MigrationPath `
            -Force
    }
}

function Resolve-SupabaseCommand {
    $Command = Get-Command supabase.exe -ErrorAction SilentlyContinue

    if (-not $Command) {
        $Command = Get-Command supabase -ErrorAction SilentlyContinue
    }

    if ($Command) {
        return @{
            Command = $Command.Source
            Prefix = @()
        }
    }

    $Npx = Get-Command npx.cmd -ErrorAction SilentlyContinue

    if (-not $Npx) {
        $Npx = Get-Command npx -ErrorAction SilentlyContinue
    }

    if (-not $Npx) {
        throw "Supabase CLI e npx não foram encontrados."
    }

    return @{
        Command = $Npx.Source
        Prefix = @("--yes", "supabase@latest")
    }
}

Write-Section "ORCALY - ENTREGADORES E HISTÓRICO DE ENTREGAS"

if (-not (Test-Path -LiteralPath (Join-Path $Root "package.json"))) {
    throw "Execute este script na raiz do projeto Orçaly."
}

if (-not (Test-Path -LiteralPath $ManagerPath)) {
    throw "Arquivo não encontrado: $ManagerRelative"
}

New-Item `
    -ItemType Directory `
    -Path $BackupRoot `
    -Force | Out-Null

Copy-Item `
    -LiteralPath $ManagerPath `
    -Destination $ManagerBackup `
    -Force

if ($HadOperations) {
    Copy-Item `
        -LiteralPath $OperationsPath `
        -Destination $OperationsBackup `
        -Force
}

Write-Host "[OK] Backup: $BackupRoot" -ForegroundColor Green

try {
    Write-Section "CRIANDO ARQUIVO DE MIGRAÇÃO LOCAL"

    New-Item `
        -ItemType Directory `
        -Path $MigrationDirectory `
        -Force | Out-Null

    $ExistingMigration = Get-ChildItem `
        -LiteralPath $MigrationDirectory `
        -Filter "*.sql" `
        -File |
        Where-Object {
            (Get-Content -LiteralPath $_.FullName -Raw) -match "ORCALY_DELIVERY_DRIVERS_ASSIGNMENTS_V1"
        } |
        Select-Object -First 1

    if ($ExistingMigration) {
        $MigrationPath = $ExistingMigration.FullName
        Write-Host "[OK] Migração já existe: $MigrationPath" -ForegroundColor Green
    }
    else {
        $Supabase = Resolve-SupabaseCommand
        $Arguments = @()

        if ($Supabase.Prefix) {
            $Arguments += $Supabase.Prefix
        }

        $Arguments += @(
            "migration",
            "new",
            "delivery_drivers_and_assignments"
        )

        & $Supabase.Command @Arguments

        if ($LASTEXITCODE -ne 0) {
            throw "Não foi possível criar a migração com Supabase CLI."
        }

        $MigrationFile = Get-ChildItem `
            -LiteralPath $MigrationDirectory `
            -Filter "*_delivery_drivers_and_assignments.sql" `
            -File |
            Sort-Object LastWriteTime -Descending |
            Select-Object -First 1

        if (-not $MigrationFile) {
            throw "Arquivo de migração criado pelo Supabase não foi localizado."
        }

        $MigrationPath = $MigrationFile.FullName
        $MigrationCreated = $true
        Write-Utf8File $MigrationPath $MigrationBase64

        Write-Host "[OK] Migração criada: $MigrationPath" -ForegroundColor Green
    }

    Write-Section "CRIANDO MÓDULO DE ENTREGADORES"

    Write-Utf8File $OperationsPath $ComponentBase64
    Write-Host "[OK] $OperationsRelative" -ForegroundColor Green

    Write-Section "INTEGRANDO À CENTRAL EXISTENTE"

    $PatcherPath = Join-Path $env:TEMP "orcaly-delivery-driver-patcher-$Timestamp.mjs"
    Write-Utf8File $PatcherPath $PatcherBase64

    try {
        node $PatcherPath $ManagerPath

        if ($LASTEXITCODE -ne 0) {
            throw "O patch da central de entregas falhou."
        }
    }
    finally {
        Remove-Item `
            -LiteralPath $PatcherPath `
            -Force `
            -ErrorAction SilentlyContinue
    }

    $ManagerContent = [System.IO.File]::ReadAllText(
        $ManagerPath,
        [System.Text.Encoding]::UTF8
    )

    $OperationsContent = [System.IO.File]::ReadAllText(
        $OperationsPath,
        [System.Text.Encoding]::UTF8
    )

    $RequiredManager = @(
        "ORCALY_DELIVERY_DRIVERS_UI_V1",
        "DeliveryDriverProvider",
        "DeliveryDriverHeaderButtons",
        "DeliveryDriverAction",
        "DeliveryDriverInfo",
        "assigned_driver_id",
        "payment_status"
    )

    foreach ($Text in $RequiredManager) {
        if (-not $ManagerContent.Contains($Text)) {
            throw "Validação da central falhou: $Text"
        }

        Write-Host "[OK] $Text" -ForegroundColor Green
    }

    $RequiredOperations = @(
        "ORCALY_DELIVERY_DRIVER_OPERATIONS_V1",
        "delivery_drivers",
        "delivery_assignments",
        "Alocar entregador",
        "Histórico de entregas",
        "Marcar prestação conferida",
        "Google Maps",
        "allocationMessage"
    )

    foreach ($Text in $RequiredOperations) {
        if (-not $OperationsContent.Contains($Text)) {
            throw "Validação do módulo falhou: $Text"
        }

        Write-Host "[OK] $Text" -ForegroundColor Green
    }

    $MigrationRelative = (
        $MigrationPath.Substring($Root.Length + 1) -replace "\\", "/"
    )

    Write-Section "VALIDANDO DIFF"

    git --no-pager diff --check -- `
        $ManagerRelative `
        $OperationsRelative `
        $MigrationRelative

    if ($LASTEXITCODE -ne 0) {
        throw "git diff --check encontrou problemas."
    }

    $Package = Get-Content `
        -LiteralPath (Join-Path $Root "package.json") `
        -Raw |
        ConvertFrom-Json

    if ($Package.scripts.PSObject.Properties.Name -contains "security:check") {
        Write-Section "VALIDANDO SEGURANÇA"

        npm run security:check

        if ($LASTEXITCODE -ne 0) {
            throw "security:check falhou."
        }

        Write-Host "[OK] SECURITY_CHECK_EXIT_CODE=0" -ForegroundColor Green
    }

    Remove-Item `
        -LiteralPath (Join-Path $Root ".next") `
        -Recurse `
        -Force `
        -ErrorAction SilentlyContinue

    Write-Section "EXECUTANDO BUILD COMPLETO"

    npm run build
    $BuildExitCode = $LASTEXITCODE

    Write-Host ""
    Write-Host "BUILD_EXIT_CODE=$BuildExitCode" -ForegroundColor Yellow

    if ($BuildExitCode -ne 0) {
        throw "O build falhou."
    }

    Write-Section "MÓDULO DE ENTREGADORES IMPLEMENTADO"

    Write-Host "Visual existente: preservado"
    Write-Host "Cadastro de entregadores: ativo"
    Write-Host "Alocação em pedidos prontos: ativa"
    Write-Host "WhatsApp com mensagem e rota: ativo"
    Write-Host "Google Maps: ativo"
    Write-Host "Histórico diário: ativo"
    Write-Host "Prestação de contas: ativa"
    Write-Host "Build: aprovado"
    Write-Host "Commit: não realizado"
    Write-Host "Deploy: não realizado"
    Write-Host "Migração local: $MigrationPath"
    Write-Host ""
    Write-Host "A migração já foi aplicada no projeto Supabase conectado." -ForegroundColor Cyan
}
catch {
    Restore-Files
    throw
}
